import sympy
from sympy import Poly, groebner
from sympy.abc import a, b, c, d, t, u, v, w, x, y, z

N_HYP = 2
NEG_Q_INDEX = 2

CONDITION_LABELS = [
    "H_1: f and g are polynomials",
    "H_2: c(h) denotes the ideal generated by the coefficients of a polynomial h",
    "¬Q: The content ideal c(fg) is not contained in the product ideal c(f)c(g)"
]

def conditions(witness):
    try:
        if isinstance(witness, tuple):
            if len(witness) == 4:
                f_in, g_in, main_var, I_rels = witness
                if not isinstance(I_rels, (list, tuple)):
                    I_rels = [I_rels]
                else:
                    I_rels = list(I_rels)
            elif len(witness) == 3:
                f_in, g_in, main_var = witness
                I_rels = []
            elif len(witness) == 2:
                f_in, g_in = witness
                f_expr = f_in.as_expr() if hasattr(f_in, 'as_expr') else f_in
                g_expr = g_in.as_expr() if hasattr(g_in, 'as_expr') else g_in
                free = set()
                if hasattr(f_expr, 'free_symbols'):
                    free.update(f_expr.free_symbols)
                if hasattr(g_expr, 'free_symbols'):
                    free.update(g_expr.free_symbols)
                x_cands = [s for s in free if s.name == 'x']
                if x_cands:
                    main_var = x_cands[0]
                elif free:
                    main_var = list(free)[0]
                else:
                    main_var = x
                I_rels = []
            else:
                return [False, False, False]
        else:
            return [False, False, False]
    except Exception:
        return [False, False, False]

    # H1: f and g are polynomials
    try:
        f_expr = f_in.as_expr() if hasattr(f_in, 'as_expr') else f_in
        g_expr = g_in.as_expr() if hasattr(g_in, 'as_expr') else g_in
        Pf = Poly(f_expr, main_var)
        Pg = Poly(g_expr, main_var)
        H1_ok = True
    except Exception:
        H1_ok = False

    # H2: c(h) denotes the ideal generated by the coefficients of a polynomial h
    H2_ok = True

    # neg_Q: The content ideal c(fg) is not contained in the product ideal c(f)c(g)
    try:
        Pfg = Poly(f_expr * g_expr, main_var)
        c_f = Pf.coeffs()
        c_g = Pg.coeffs()
        c_fg = Pfg.coeffs()
        
        c_f_c_g = []
        for cf in c_f:
            for cg in c_g:
                c_f_c_g.append(cf * cg)
                
        I_rels_expr = [rel.as_expr() if hasattr(rel, 'as_expr') else rel for rel in I_rels]
        all_exprs = c_f + c_g + c_fg + I_rels_expr
        
        vars_set = set()
        for expr in all_exprs:
            if hasattr(expr, 'free_symbols'):
                vars_set.update(expr.free_symbols)
        if main_var in vars_set:
            vars_set.remove(main_var)
        vars_list = list(vars_set)
        
        if not vars_list and I_rels_expr:
            dummy = sympy.Symbol('dummy_var_for_groebner')
            vars_list = [dummy]
            
        if not vars_list:
            try:
                gcd_f = sympy.gcd_list(c_f)
                gcd_g = sympy.gcd_list(c_g)
                gcd_fg = sympy.gcd_list(c_fg)
                prod_gcd = gcd_f * gcd_g
                if prod_gcd == 0:
                    neg_Q_ok = (gcd_fg != 0)
                else:
                    neg_Q_ok = (gcd_fg % prod_gcd != 0)
            except Exception:
                neg_Q_ok = False
        else:
            G_prod = groebner(c_f_c_g + I_rels_expr, *vars_list)
            contained = True
            for c_val in c_fg:
                if G_prod.reduce(c_val)[1] != 0:
                    contained = False
                    break
            neg_Q_ok = not contained
            
    except Exception:
        neg_Q_ok = False

    return [H1_ok, H2_ok, neg_Q_ok]